from snack_check import DB, tol, CALC_TOL  # noqa: F401  (같은 식약처 파일·같은 허용 범위)

CHECKED = '2026-10-14'


def calc_kcal(s):
    """표시값으로 계산한 열량: (탄수화물-식이섬유-알룰로오스)x4 + 식이섬유x2 + 단백질x4 + 지방x9"""
    fi = s.get('fi', 0) or 0
    al = s.get('allulose', 0) or 0
    return (s['c'] - fi - al) * 4 + fi * 2 + s['p'] * 4 + s['f'] * 9


