# 포장 영양정보를 화면에 표시 그대로 보여 주기(표시 순서·단위 그대로, 값은 X의 show에서 만듦)
_NAMES = [('na', '나트륨', 'mg'), ('c', '탄수화물', 'g'), ('s', '당류', 'g'), ('lac', '유당', 'g'), ('fi', '식이섬유', 'g'),
          ('allulose', '알룰로오스', 'g'), ('f', '지방', 'g'), ('tf', '트랜스지방', 'g'), ('sf', '포화지방', 'g'),
          ('chol', '콜레스테롤', 'mg'), ('p', '단백질', 'g'), ('ca', '칼슘', 'mg'), ('fe', '철분', 'mg'), ('vd', '비타민 D', 'μg')]
_TOTAL = {'mk_lf_milk_orig': '930ml', 'mk_lf_milk_low': '930ml'}


def _v(x):
    if isinstance(x, str) and x.startswith('<'):
        return x[1:] + '{u} 미만'
    return ('%g' % x) + '{u}'


def plabel(v):
    s = v['show']
    base = f"100{v['u']}당" if v['w'] == 100 else f"총 내용량 {v['w']}{v['u']}당"
    parts = [f"{s['kcal']}kcal"] + [n + ' ' + _v(s[k]).format(u=u) for k, n, u in _NAMES if k in s]
    tot = f" (총 내용량 {_TOTAL[v['fid']]})" if v['fid'] in _TOTAL else ''
    return f"{base}{tot}: " + ' · '.join(parts) + f". 포장 표시({CHECKED} 확인)"


PLABEL = {v['fid']: plabel(v) for v in X.values()}

